        settings_max_result_window_hint: '⚠ Graylog API 匯出會在 Graylog 的 index.max_result_window（OpenSearch 預設為 10000）範圍內分頁。jt-glogarch 會自動將每次請求控制在此上限內，通常無需調整。若您的叢集已將 max_result_window 調低於 10000，請將其還原為至少 10000，否則 API 模式匯出可能出現「Result window is too large」錯誤。OpenSearch：PUT <index>/_settings {"index.max_result_window":10000}。',
